/* ---- WORLD 2: PAINTINGS ON THE WALL — the pictures take turns, one fading into the next ---- */
const WALL = [[14, 28, 37, 26], [57, 28, 37, 26]];      // the two frames: x, y, width, height (canvas pixels)
let wallRun = 0, wallZ = 1;
const matCache = new Map();
function matColor(img) {                                // the picture's own edge colour fills the space around it, so any shape fits the frame
  if (matCache.has(img.src)) return matCache.get(img.src);
  let col = "#150c1e";
  try {
    const c = document.createElement("canvas"); c.width = c.height = 24; const x = c.getContext("2d"); x.drawImage(img, 0, 0, 24, 24);
    const d = x.getImageData(0, 0, 24, 24).data; let r = 0, g = 0, b = 0, n = 0;
    for (let i = 0; i < 24; i++) for (let j = 0; j < 24; j++) if (i === 0 || j === 0 || i === 23 || j === 23) { const p = (j * 24 + i) * 4; r += d[p]; g += d[p + 1]; b += d[p + 2]; n++; }
    col = `rgb(${Math.round(r / n)},${Math.round(g / n)},${Math.round(b / n)})`;
  } catch (e) {}
  matCache.set(img.src, col); return col;
}
function buildWall(w) {
  WALL.forEach(([x, y, fw, fh]) => {
    const s = mk("wall-art", "", w, "button");
    Object.assign(s.style, { left: x / PW * 100 + "%", top: y / PH * 100 + "%", width: fw / PW * 100 + "%", height: fh / PH * 100 + "%" });
    s.setAttribute("aria-label", "painting: click to see it bigger");
    s._imgs = [mk("wa-img", "", s, "img"), mk("wa-img", "", s, "img")]; s._imgs.forEach(i => i.alt = ""); s._front = 0; s._cur = null;
    s.onclick = () => {
      if (!s._cur) return;
      const z = mk("wall-zoom", "", document.body), im = mk("", "", z, "img"); im.src = s._cur;
      const close = () => { z.remove(); document.removeEventListener("keydown", esc); }, esc = e => e.key === "Escape" && close();
      z.onclick = close; document.addEventListener("keydown", esc);
    };
  });
}
function showOnWall(s, img) {                           // the new picture fades in over the old one
  const back = s._imgs[1 - s._front], old = s._imgs[s._front];
  back.src = img.src; back.style.zIndex = ++wallZ; s.style.backgroundColor = matColor(img); s._cur = img.src;
  void back.offsetWidth; back.classList.add("on"); s._front = 1 - s._front;
  setTimeout(() => old.classList.remove("on"), 1800);
}
async function runWall() {
  const run = ++wallRun, srcs = CONFIG.wallPics || [], slots = $$(".wall-art");
  if (!srcs.length || !slots.length) return;
  const imgs = (await Promise.all(srcs.map(loadImg))).filter(Boolean); if (run !== wallRun || !imgs.length) return;
  slots.forEach(async (s, k) => {                       // each painting walks through every other picture; the second starts a little later
    let j = k; await wait(k * (CONFIG.wallSeconds || 7) * 550);
    while (run === wallRun) { showOnWall(s, imgs[j % imgs.length]); j += slots.length; await wait((CONFIG.wallSeconds || 7) * 1000); }
  });
}

