let coupleRun = 0;
function buildCouple(w) {
  const d = mk("couple-wrap", COUPLE_SVG, w);
  Object.assign(d.style, { left: 10 / PW * 100 + "%", top: 51 / PH * 100 + "%", width: 86 / PW * 100 + "%", height: 34.5 / PH * 100 + "%" });
}
function cuddleHeart(w, big) {                          // a smooth little vector heart that drifts up and fades
  const sz = big ? rnd(26, 36) : rnd(14, 24), col = ["#ff5b8a", "#ff8fb4", "#ffb3d0", "#ff6b81", "#c98bff"][Math.floor(rnd(0, 5))];
  const h = mk("cuddle-heart", `<svg viewBox="0 0 32 29" width="100%" height="100%"><path d="M16 28C4 18 0 12 0 8C0 3 4 0 8 0C11 0 14 2 16 5C18 2 21 0 24 0C28 0 32 3 32 8C32 12 28 18 16 28Z" fill="${col}"/><ellipse cx="9" cy="8" rx="3.2" ry="2" fill="#fff" opacity=".55" transform="rotate(-30 9 8)"/></svg>`, w);
  h.style.left = (38 + rnd(-8, 8)) / PW * 100 + "%"; h.style.top = 58 / PH * 100 + "%"; h.style.width = sz + "px"; h.style.height = sz * .9 + "px";
  h.style.filter = `drop-shadow(0 0 6px ${col})`; h.style.setProperty("--dx", rnd(-45, 45) + "px"); h.style.setProperty("--r", rnd(-25, 25) + "deg");
  setTimeout(() => h.remove(), 4200);
}
function runCouple() {                                  // (the cuddling itself is pure CSS; this only releases the hearts, in step with it)
  const run = ++coupleRun, w = $('.world[data-world="2"]'); $$(".cuddle-heart", w).forEach(e => e.remove());
  const svg = $(".cp-svg", w); svg.classList.remove("go"); void svg.getBoundingClientRect(); svg.classList.add("go");   // restart the 8-second cuddle loop
  (async () => {
    let t = 0;
    while (run === coupleRun) {
      await wait(1300); t += 1.3; if (run !== coupleRun) return;
      cuddleHeart(w, false);
    }
  })();
  (async () => {
    await wait(4300);                                   // the nuzzle moment of each loop: a burst of bigger hearts
    while (run === coupleRun) { for (let i = 0; i < 4; i++) { if (run !== coupleRun) return; cuddleHeart(w, true); await wait(260); } await wait(8000 - 4 * 260); }
  })();
}

function frame(x, y, w, h, inner) { R(x - 2, y - 2, w + 4, h + 4, "#d9a85a"); R(x - 1, y - 1, w + 2, h + 2, "#8a5a2a"); R(x, y, w, h, "#000"); inner(x, y, w, h); }
const BOOKCOL = [["#c0405a", "#7a1f3a"], ["#6a5ad8", "#3a2a8a"], ["#3fa58a", "#1f6a55"], ["#e0a040", "#8a5a1a"], ["#d87ab0", "#8a3a6a"], ["#4a8ad8", "#2a4a8a"], ["#8a5ad8", "#4a2a8a"], ["#d86a4a", "#8a3a2a"]];
