function shootingStar() {            // keeps coming back, carrying the wish
  if (state.world !== 1) return;
  const s = mk("shooting-star", `<span class="star-message">you're my prettiest wish ✦</span>`, $("#shootingStars"));
  s.onclick = e => { sparkle(e.clientX, e.clientY, "✦", 12); showDialogue("make a wish. i already did.", 3500); };
  setTimeout(() => s.remove(), 8200);
}

