  for (let y = 8; y < 54; y += 10) for (let x = 4 + ((y / 10) % 2) * 4; x < PW; x += 8) R(x, y, 1, 1, "#4a3068");
  R(0, 56, PW, 2, "#e2ad44"); R(0, 58, PW, 14, "#3a2230"); for (let x = 0; x < PW; x += 12) R(x, 60, 1, 10, "#2a1822"); R(0, 70, PW, 2, "#241420");   // rail + wainscot
  for (let y = 72; y < PH; y += 4) R(0, y, PW, 4, (y / 4) % 2 ? "#5a3426" : "#4e2c20");                         // wooden floor
