  R(cx - 6 + sw, 51 + hy, 5, 3, "#07070d"); R(cx + 1 + sw, 51 + hy, 5, 3, "#07070d"); R(cx - 1 + sw, 51 + hy, 2, 1, "#07070d"); R(cx - 5 + sw, 51 + hy, 1, 1, "#8a8ac0"); R(cx + 2 + sw, 51 + hy, 1, 1, "#8a8ac0");   // dark glasses
  if (open) { R(cx - 2 + sw, 55 + hy, 4, 3, "#2a0a14"); R(cx - 1 + sw, 57 + hy, 2, 1, "#d9687a"); } else R(cx - 2 + sw, 56 + hy, 4, 1, "#8a3a3a");
  R(cx - 2 + sw, 54 + hy, 1, 1, skin2);
