  R(cx - 8, 90, 16, 3, dress); R(cx - 8, 92, 16, 1, dress2);                                                         // skirt over the seat
  R(cx - 10, 92, 20, 6, ch); R(cx - 10, 92, 20, 1, ch2); R(cx - 10, 96, 20, 2, ch3);                                 // seat cushion
  R(cx - 5, 93, 4, 5, skin); R(cx + 1, 93, 4, 5, skin); R(cx - 5, 93, 4, 1, dress2); R(cx + 1, 93, 4, 1, dress2);   // legs
  R(cx - 6, 98, 5, 2, "#8a2f5e"); R(cx + 1, 98, 5, 2, "#8a2f5e");                                                   // shoes
