  R(cx - 6, 71 + hy, 3, 1, hair); R(cx + 3, 71 + hy, 3, 1, hair); R(cx - 7, 67 + hy, 14, 3, hair); R(cx - 5, 66 + hy, 9, 1, hair2);
  R(cx - 7, 67 + hy, 2, 2, "#ffd36b");                                                                              // star clip
