function buildConcert() {
  if (CNC.ov) return;
  const bubble = [[1090, 300, 85], [1170, 235, 95], [1290, 232, 100], [1395, 290, 85], [1335, 358, 85], [1190, 360, 85], [1240, 300, 112]], trail = [[1212, 518, 11], [1188, 476, 17]];
  const out = [...bubble, ...trail].map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#fff" stroke-width="9"/>`).join("");
  const fill = [...bubble, ...trail].map(([x, y, r]) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#000"/>`).join("");   // cut out the middle: the bubble is see-through
  const word = (w, o) => [...w].map((ch, i) => `<span style="--i:${o + i}">${ch}</span>`).join("");
  const ov = CNC.ov = document.createElement("div"); ov.className = "cnc hidden"; ov.setAttribute("role", "button"); ov.setAttribute("aria-label", "tap to go back to the garden");
  ov.innerHTML = `<div class="cnc-stage"><canvas class="cnc-px" width="${PW}" height="${PH}"></canvas>
    <svg class="cnc-fg" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid meet" aria-hidden="true">
      <defs><filter id="cncWob" x="-12%" y="-20%" width="124%" height="140%"><feTurbulence type="fractalNoise" baseFrequency=".011 .019" numOctaves="2" seed="4" result="n"><animate attributeName="baseFrequency" dur="7s" values=".011 .019;.02 .011;.011 .019" repeatCount="indefinite"/></feTurbulence><feDisplacementMap in="SourceGraphic" in2="n" scale="22" xChannelSelector="R" yChannelSelector="G"/></filter></defs>
      <mask id="cncRing" maskUnits="userSpaceOnUse" x="0" y="0" width="1600" height="900"><rect width="1600" height="900" fill="#000"/>${out}${fill}</mask>
      <g transform="translate(50 85)"><g class="cnc-bub"><g transform="translate(1240 300) scale(.44) translate(-1240 -300)"><g filter="url(#cncWob)"><rect width="1600" height="900" fill="#e9cdfa" fill-opacity=".8" mask="url(#cncRing)"/></g></g></g></g>
    </svg>
    <div class="cnc-tag cnc-tag-guy">zyad</div><div class="cnc-tag cnc-tag-girl">jia</div>
    <div class="cnc-say" aria-label="koi bachaye mujhey"><div>${word("koi", 0)}<i></i>${word("bachaye", 4)}</div><div>${word("mujhey", 11)}</div></div></div>
    <div class="cnc-hint">tap anywhere to go back to the garden</div>`;
  document.body.appendChild(ov);
  CNC.cv = $(".cnc-px", ov); CNC.bg = cncBg();
  ov.addEventListener("click", closeConcert);
}
function openConcert(from) {
  buildConcert(); if (CNC.open) return; CNC.open = true;
  const ov = CNC.ov, r = from.getBoundingClientRect();
  dialogue.classList.add("hidden");
  ov.style.transformOrigin = `${r.left + r.width / 2}px ${r.top + r.height / 2}px`;
  ov.classList.remove("hidden", "out", "in"); void ov.offsetWidth; ov.classList.add("in");
  CNC.f = -1; CNC.t0 = performance.now();
  const loop = now => {
    CNC.raf = requestAnimationFrame(loop); const f = Math.floor((now - CNC.t0) / 125); if (f !== CNC.f) { CNC.f = f; cncFrame(f); }
  };
  cancelAnimationFrame(CNC.raf); CNC.raf = requestAnimationFrame(loop);
}
function closeConcert() {
  if (!CNC.open) return; CNC.open = false; const ov = CNC.ov;
  ov.classList.remove("in"); ov.classList.add("out");
  setTimeout(() => { if (!CNC.open) { ov.classList.add("hidden"); ov.classList.remove("out"); cancelAnimationFrame(CNC.raf); } }, 620);
}
document.addEventListener("keydown", e => { if (e.key === "Escape") closeConcert(); });

/* Funny system glitch */
function glitch(txt) {
  const g = $("#game"); g.style.transition = "none"; g.style.filter = "hue-rotate(120deg) saturate(2)"; g.style.transform = "translateX(6px) skewX(3deg)";
  if (txt) showDialogue(txt, 3000);
  setTimeout(() => { g.style.filter = ""; g.style.transform = ""; }, 350);
}
setInterval(() => { if (state.musicOn !== null && Math.random() < .25 && $("#game").classList.contains("visible")) glitch(); }, 45000);

/* =========================================================
   THE HAND — low on the right; jumps, waves, blows hearts
   ========================================================= */
const hand = $("#journeyHand"), handBtn = $("#handButton"), handMsg = $("#handMsg"), bloom = $("#bloomOverlay");
let idleTimer;
function idleTricks() {
  clearInterval(idleTimer);
  idleTimer = setInterval(() => {
    if (hand.classList.contains("hidden")) return;
    const t = ["jump", "wave", "heart"][Math.floor(rnd(0, 3))];
    if (t === "heart") { const h = mk("hand-heart", "♥", handBtn, "span"); setTimeout(() => h.remove(), 1900); }
    else { handBtn.classList.add(t); setTimeout(() => handBtn.classList.remove(t), 1300); }
  }, 3200);
}
function bloomTransition(colors, mid) {
  colors.forEach((c, i) => bloom.style.setProperty("--c" + (i + 1), c));
  bloom.classList.remove("hidden"); bloom.classList.add("bloom-active");
  setTimeout(mid, 650);
  setTimeout(() => { bloom.classList.remove("bloom-active"); bloom.classList.add("hidden"); }, 1450);
}
function offerHand(msg, colors, next) {
  const wasHidden = hand.classList.contains("hidden");
  handMsg.textContent = msg; hand.classList.remove("hidden", "leaving");
  if (wasHidden) idleTricks();
  let used = false;                                  // one click = one trip (a double-click can't fire twice)
  handBtn.onclick = () => {
    if (used) return; used = true;
    clearInterval(idleTimer); hand.classList.add("leaving");
    setTimeout(() => hand.classList.add("hidden"), 400);
    bloomTransition(colors, () => switchWorld(next));
  };
}
const hideHand = () => { clearInterval(idleTimer); hand.classList.add("hidden"); hand.classList.remove("leaving"); };

/* =========================================================
   WORLD SWITCHING
   ========================================================= */
/* ---- THE BACK HAND (left side): "you can always come back with me" ---- */
const backHand = $("#backHand"); let backT;
function hideBack() { clearTimeout(backT); backHand.classList.add("hidden"); }
function showBack(n) { hideBack(); if (n <= 1) return;    // the back arms are in every world now, including the house and the birthday room
  backT = setTimeout(() => backHand.classList.remove("hidden"), 1800); }
$("#backBtn").onclick = () => {
  const cols = ["#7ad7ff", "#c98bff", "#ff9ac9"];
  if (state.world === 7) {
    if (finPhase === "going") return;                       // she is mid-walk through the door: wait
    if (finPhase !== "street") {                            // birthday room -> back out to the house
      hideBack(); bloomTransition(cols, () => { runFinale(); showBack(7); }); return;
    }
  }
  const prev = state.world - 1; if (prev < 1) return;      // house -> the shore, and every other world -> the one before
  hideBack(); bloomTransition(cols, () => switchWorld(prev));
};

let worldTimer;
function switchWorld(n) {
  if (n < 1 || n > 7) return;
  $$(".world").forEach(w => w.classList.toggle("active", Number(w.dataset.world) === n));
  state.world = n; save(); $("#worldLabel").textContent = worldNames[n];
  dialogue.classList.add("hidden"); hideHand(); hideBack(); clearTimeout(worldTimer); stopMeteors(); songAudio.pause(); closeBookView(); sunRun++; wallRun++; coupleRun++; flightRun++; if (n !== 7) finStop(); $$(".wall-zoom").forEach(e => e.remove()); document.body.classList.remove("reading");
  document.body.classList.toggle("light-world", n === 3);
  document.body.classList.toggle("shore", n === 6);        // lets the corner texts stay readable while the sunset changes colour   // world 3 is the bright daytime picnic
  setMusic(n); showBack(n);
  const handOffers = {
    1: ["take my hand. let me take you through my heart that you already own.", ["#ff5b8a", "#c98bff", "#ffb37a"], 2],
    2: ["come see the pictures →", ["#7ad7ff", "#c98bff", "#ff9ac9"], 3],
    3: ["now let me take you inside my heart →", ["#ff5b8a", "#ffd39a", "#c98bff"], 4],
    4: ["come a little further →", ["#ff5b8a", "#ffd39a", "#c98bff"], 5],
    5: ["somewhere quieter →", ["#ff9ac9", "#ffffff", "#c98bff"], 6],
    6: [SHORE.hand, ["#ff9ac9", "#ffd39a", "#c98bff"], 7]    // the shore's hand is there from the first second, in the corner
  };
  if (handOffers[n] && n !== 3) offerHand(...handOffers[n]);   // the forward hand is always there

  if (n === 2) { buildBooks(); runWall(); runCouple(); }
  if (n === 3) { showDialogue(`<strong>THE PICNIC</strong><br>tap the pictures to turn the page.`, 3500); runStory(); }
  if (n === 4) { buildEnvelopes(); showDialogue(`<strong>INSIDE MY HEART</strong><br>hover an envelope for its title. open the ones that call to you.`, 5000); }
  if (n === 5) { setTimeout(() => startFlight(), 600); }
  if (n === 6) runSunset();
  if (n === 7) runFinale();
}

/* ---- WORLD 2: GALLERY BOOK — batches of pictures with a pointing finger.
        click finger/pictures -> batch pixelates & vanishes -> next batch develops from pixels ---- */
const GAL_LONG = 520;
function drawFit(c, img, res, idx) {                    // whole picture (no square crop), drawn small then scaled up = pixelated
  const ctx = c.getContext("2d"), a = c.width / c.height, t = document.createElement("canvas");
  t.width = Math.max(2, Math.round(a >= 1 ? res : res * a)); t.height = Math.max(2, Math.round(a >= 1 ? res / a : res));
  const tx = t.getContext("2d");
  if (img) tx.drawImage(img, 0, 0, t.width, t.height);
  else { const g = tx.createLinearGradient(0, 0, t.width, t.height); g.addColorStop(0, ["#ff9ac9", "#c98bff", "#7ad7ff", "#ffd39a"][idx % 4]); g.addColorStop(1, "#3a2568"); tx.fillStyle = g; tx.fillRect(0, 0, t.width, t.height); }
  ctx.imageSmoothingEnabled = false; ctx.clearRect(0, 0, c.width, c.height); ctx.drawImage(t, 0, 0, c.width, c.height);
}
async function openGallery(bk) {
  const v = mk("book-view gallery", "", $('.world[data-world="2"]'));
  const x = mk("gal-close", "×", v, "button"); x.setAttribute("aria-label", "close"); x.onclick = closeBookView;
  const stage = mk("gal-stage", "", v), box = mk("gal-groups", "", stage);
  const point = mk("gal-point hidden", '<span class="finger">👆</span><small>click</small>', stage, "button");
  const alive = () => v.isConnected, tilts = [-3, 2.5, -2, 3];
  for (const batch of bk.batches) {
    if (!alive()) return;
    box.innerHTML = ""; point.classList.add("hidden");
    const loaded = await Promise.all(batch.map(g => Promise.all(g.photos.map(loadImg))));
    if (!alive()) return;
    const pics = [], caps = []; let n = 0;
    batch.forEach((g, gi) => {
      const grp = mk("gal-group", "", box), row = mk("gal-pics", "", grp);
      g.photos.forEach((_, pi) => {
        const img = loaded[gi][pi], asp = img ? img.width / img.height : 3 / 4;
        const f = mk("gal-pic jumpin", "", row, "button"); f.style.setProperty("--gr", tilts[n % 4] + "deg"); f.style.animationDelay = n * 0.15 + "s";
        const c = mk("", "", f, "canvas"); c.width = Math.round(asp >= 1 ? GAL_LONG : GAL_LONG * asp); c.height = Math.round(asp >= 1 ? GAL_LONG / asp : GAL_LONG);
        pics.push({ f, c, img, idx: n++ });
      });
      caps.push(mk("gal-cap" + (g.wide ? " wide" : ""), g.text || "", grp));
    });
    for (const r of [8, 16, 32, 64, 120, 260, GAL_LONG]) { if (!alive()) return; pics.forEach(p => drawFit(p.c, p.img, r, p.idx)); await wait(100); }   // develops from pixels
    caps.forEach(c => c.classList.add("show")); await wait(500); if (!alive()) return;
    point.classList.remove("hidden");
    await new Promise(res => { point.onclick = res; pics.forEach(p => p.f.onclick = res); });
    if (!alive()) return;
    point.classList.add("hidden"); caps.forEach(c => c.classList.remove("show"));
    for (const r of [260, 120, 60, 32, 18, 10, 6]) { pics.forEach(p => drawFit(p.c, p.img, r, p.idx)); await wait(110); }   // pixelate...
    pics.forEach(p => p.f.classList.add("vanish")); await wait(600);                                                      // ...and vanish
  }
  closeBookView();
}

