/* ---- WORLD 2: "globebook" — open the book, click the globe, it lifts off the paper, spins, finds multan ---- */
const GB_POLY = {
  na: [[-168,66],[-140,70],[-120,70],[-95,72],[-80,68],[-62,60],[-56,50],[-66,44],[-76,36],[-81,26],[-97,27],[-97,18],[-88,15],[-80,8],[-92,14],[-105,20],[-112,30],[-124,40],[-124,48],[-135,58],[-155,58]],
  sa: [[-80,9],[-72,12],[-60,10],[-50,0],[-35,-6],[-40,-22],[-48,-28],[-58,-38],[-66,-46],[-70,-54],[-75,-46],[-72,-30],[-70,-18],[-81,-5]],
  gr: [[-55,60],[-45,60],[-20,70],[-20,82],[-60,82],[-70,76]],
  eu: [[-10,36],[-9,43],[-2,48],[5,52],[8,57],[5,62],[15,69],[28,71],[45,68],[70,73],[100,77],[140,72],[170,70],[180,66],[160,58],[142,52],[135,43],[127,36],[122,30],[120,22],[108,18],[106,10],[100,13],[98,8],[100,2],[93,17],[88,22],[80,15],[77,8],[73,18],[68,24],[57,25],[56,27],[48,30],[50,26],[56,24],[59,22],[43,13],[35,28],[34,31],[27,37],[26,40],[19,40],[16,38],[12,44],[3,43],[-5,36]],
  af: [[-17,21],[-10,30],[-6,36],[10,37],[20,32],[32,31],[34,28],[43,12],[51,12],[41,-2],[40,-15],[35,-25],[27,-34],[18,-34],[12,-18],[9,-1],[9,5],[-8,4],[-17,14]],
  au: [[114,-22],[122,-18],[131,-12],[137,-12],[142,-11],[146,-19],[153,-27],[150,-37],[141,-38],[130,-32],[115,-34]],
  uk: [[-6,50],[2,51],[0,58],[-6,58]], jp: [[130,32],[141,36],[142,43],[140,41]],
  an: [[-180,-72],[-120,-75],[-60,-70],[0,-70],[60,-68],[120,-66],[180,-72],[180,-90],[-180,-90]]
};
const GB_PK = [[61,25],[66,25],[71,24],[71,28],[75,31],[74,35],[77,36],[75,37],[71,36],[70,34],[66,30],[62,29]];
const GB_MULTAN = { lon: 71.47, lat: 30.2 };
let GB_DOTS = null;
function gbIn(pt, poly) { let c = false; for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) { const a = poly[i], b = poly[j]; if ((a[1] > pt[1]) !== (b[1] > pt[1]) && pt[0] < (b[0] - a[0]) * (pt[1] - a[1]) / (b[1] - a[1]) + a[0]) c = !c; } return c; }
function gbDots() {
  if (GB_DOTS) return GB_DOTS;
  const out = [], polys = Object.values(GB_POLY), step = 3.4;
  for (let la = -84; la <= 82; la += step) { const ls = step / Math.max(Math.cos(la * Math.PI / 180), .25);
    for (let lo = -180; lo < 180; lo += ls) if (polys.some(p => gbIn([lo, la], p))) { const f = la * Math.PI / 180; out.push({ sf: Math.sin(f), cf: Math.cos(f), l: lo * Math.PI / 180, pk: gbIn([lo, la], GB_PK) }); } }
  return (GB_DOTS = out);
}
