    R("#5a3a22", 4, -10, 9, 1); R(v.shirt, -4, -19, 4, 8); R(v.skin, -3, -23, 3, 4); R("#f1ede2", -3, -24, 3, 2);
    R("#8c8590", 12, -15, 13, 6); R("#a8a2ae", 12, -15, 13, 1); R("#8c8590", 24, -19, 5, 5); R("#a8a2ae", 28, -17, 2, 3); R("#8c8590", 24, -22, 1, 3); R("#8c8590", 26, -22, 1, 3); R("#1d1410", 27, -18, 1, 1);
