    tr.gain.value = .75; const lfo = ac.createOscillator(), lg = ac.createGain(); lfo.frequency.setValueAtTime(20, t); lfo.frequency.linearRampToValueAtTime(46, pk); lfo.frequency.linearRampToValueAtTime(24, end); lg.gain.value = .25; lfo.connect(lg); lg.connect(tr.gain);
