    vehicles.forEach(v => ents.push({ y: v.y, f: () => { ctx.save(); ctx.translate(Math.round(v.x), Math.round(v.y)); ctx.scale(v.dir, 1); (v.kind === "bike" ? drawBike : v.kind === "rick" ? drawRick : v.kind === "car" ? drawCar : drawDonkey)(v, el); ctx.restore(); } }));
    ents.sort((a, b) => a.y - b.y).forEach(e => e.f());
    parts.forEach(q => { ctx.globalAlpha = Math.max(0, q.l / q.m) * .7; R(q.c, Math.round(q.x), Math.round(q.y), q.s, q.s); }); ctx.globalAlpha = 1;
