  const K = girl ? { hair: "#5a2a1e", hair2: "#7a3a2a", skin: "#f6cba8", top: "#ff8fb4", top2: "#e86a98", pants: "#ff8fb4", shoe: "#8a3a4a" }
                 : { hair: "#2e1c14", hair2: "#4a2c1e", skin: "#f2c29b", top: "#4a8ad8", top2: "#3a6ab0", pants: "#3a3f6a", shoe: "#2a1a12" };
