  rc(HX, HY, 7, 6, K.skin);
  rc(HX, HY - 1, 7, 2, K.hair); rc(HX - 1, HY, 3, girl ? 3 : 5, K.hair); rc(HX + 3, HY, 4, 1, K.hair);
  if (girl) { rc(HX + 1, HY - 2, 3, 2, "#ffffff"); rc(HX + 2, HY - 2, 1, 2, "#ff8fb4"); }
  if (o.happy) rc(HX + 4, HY + 3, 2, 1, eye); else rc(HX + 4, HY + 2, 1, 2, eye);
