    if (pose === "sitReach") { rc(10, ty + 2, 4, 2, K.top); rc(14, ty + 2, 3, 2, K.skin); }
    else if (pose === "sitGet") { rc(10, ty + 3, 4, 2, K.top); rc(14, ty + 3, 3, 2, K.skin); }
