  let fs = Math.floor(100 * W * (portrait ? .9 : .6) / widest); fs = Math.min(fs, Math.floor(H * (portrait ? .13 : .16)));
  o.font = fam(fs); o.textAlign = "center"; o.textBaseline = "middle"; o.fillStyle = "#fff";
  const lh = fs * 1.2, cy = H * (portrait ? .26 : .27);
  lines.forEach((l, i) => o.fillText(l, W / 2, cy + (i - (lines.length - 1) / 2) * lh));
