  for (let y = 0; y < H; y += gap) for (let x = 0; x < W; x += gap) if (data[(y * W + x) * 4 + 3] > 128) pts.push([x + (Math.random() - .5) * gap * .9, y + (Math.random() - .5) * gap * .9]);
